#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_render_root_candidate.h"
#include "graph_transform_hierarchy.h"
#include "film_track_selection_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto g=loadGraph(argv[1]);std::map<uint32_t,uint32_t>parents;for(uint32_t id=0;id<g.elements.size();++id){auto&e=g.elements[id];if(!namedAttribute(g,e,"transform"))continue;for(auto child:hierarchyRefs(g,e,"children",15)){auto z=parents.emplace(child,id);if(!z.second&&z.first->second!=id)std::cout<<"duplicate_parent child="<<child<<" childType="<<g.strings.at(g.elements[child].type)<<" childName="<<g.strings.at(g.elements[child].name)<<" parentA="<<z.first->second<<":"<<g.strings.at(g.elements[z.first->second].type)<<":"<<g.strings.at(g.elements[z.first->second].name)<<" parentB="<<id<<":"<<g.strings.at(e.type)<<":"<<g.strings.at(e.name)<<"\n";}}for(uint32_t target:{13180u,13860u}){std::cout<<"target="<<target<<":"<<g.strings.at(g.elements[target].type)<<":"<<g.strings.at(g.elements[target].name)<<"\n";for(uint32_t id=0;id<g.elements.size();++id)if(namedAttribute(g,g.elements[id],"transform"))for(auto child:hierarchyRefs(g,g.elements[id],"children",15))if(child==target)std::cout<<" parent="<<id<<":"<<g.strings.at(g.elements[id].type)<<":"<<g.strings.at(g.elements[id].name)<<"\n";}auto root=sessionRenderRootCandidate(g);std::cout<<"elements="<<g.elements.size()<<" root="<<root<<" type="<<g.strings.at(g.elements.at(root).type)<<" name="<<g.strings.at(g.elements.at(root).name)<<"\n";auto track=filmClipTrackCandidate(g,root);if(track){std::cout<<"root_track="<<*track<<" name="<<g.strings.at(g.elements[*track].name)<<"\n";for(auto c:hierarchyRefs(g,g.elements[*track],"children",15)){if(g.strings.at(g.elements[c].type)!="DmeFilmClip")continue;auto t=hierarchyRefs(g,g.elements[c],"timeFrame",1);AnimationTimeFrame f(g,g.elements.at(t.at(0)));auto camera=hierarchySingleReference(g,g.elements[c],"camera"),scene=hierarchySingleReference(g,g.elements[c],"scene");std::cout<<"child="<<c<<" name="<<g.strings.at(g.elements[c].name)<<" start="<<f.start<<" duration="<<f.duration<<" camera="<<camera<<" scene="<<scene<<"\n";}}for(auto&a:g.elements.at(root).attributes){std::cout<<"root_attr="<<g.strings.at(a.name)<<" type="<<unsigned(a.type)<<" n="<<a.values.size();for(auto&v:a.values)std::cout<<" ref="<<v.reference<<(v.reference<g.elements.size()?":"+g.strings.at(g.elements[v.reference].type)+":"+g.strings.at(g.elements[v.reference].name):"");std::cout<<"\n";}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
